from format_lecon import Lesson,paras,table,steps
from diagnostics import DIAGNOSTICS
def make(n):return Lesson(DIAGNOSTICS[n-1][0],n)

l=make(4)
l.add('Le polype vocal est une lésion bénigne généralement unilatérale du pli vocal. Ses {caractéristiques propres} le distinguent des nodules bilatéraux et des lésions sous-muqueuses.',paras('Il peut faire suite à un traumatisme vocal avec atteinte vasculaire et remaniement local. Son implantation et son volume varient ; le nom de polype ne doit pas être attribué à toute masse observée.', 'Il perturbe la vibration ou la fermeture, parfois avec une réaction du pli opposé. Cette réaction ne transforme pas automatiquement la lésion en nodules bilatéraux.'),(3,6))
l.add('L’effort vocal intense est un contexte possible, sans être obligatoire. Les {données de contexte} ne permettent pas d’établir une incidence suisse spécifique.',paras('Les HUG décrivent une association avec un traumatisme ou un hématome local. Le patient peut identifier un événement vocal ou rapporter une évolution moins nette. Une histoire de cris ne suffit donc ni à confirmer ni à exclure le diagnostic.', 'Le tabagisme et les autres irritants doivent être recherchés dans le bilan laryngé, surtout pour apprécier les diagnostics concurrents. Les sources retenues ne donnent pas de classement chiffré des polypes parmi les causes de dysphonie.'),(3,6))
l.add('Une masse focale déséquilibre la vibration des deux plis. Les {conséquences mécaniques} dépendent aussi de sa position et de son effet sur l’accolement.',paras('Le relief peut empêcher une fermeture complète, augmenter la fuite d’air et modifier la régularité vibratoire. La voix associe alors parfois raucité, souffle et fatigabilité.', 'Le patient peut forcer pour compenser cette fuite. La prise en charge du geste reste utile même lorsque la lésion structurale nécessite une exérèse ; les deux objectifs sont complémentaires.'),(2,3,6))
l.add('La première étape est de vérifier que la lésion est compatible avec un polype bénin. Les {situations suspectes} changent l’objectif de l’exploration.',table(['🚩 Situation','Décision'],[['Aspect irrégulier ou ulcéré, mobilité réduite.','Explorer une lésion potentiellement maligne ou une atteinte plus profonde.'],['Tabac, progression ou masse cervicale.','Accélérer le bilan spécialisé sans présumer un simple polype.'],['Modification brutale après effort.','Rechercher notamment une lésion hémorragique et éviter de poursuivre le forçage.'],['Gêne respiratoire.','Évaluer la perméabilité des voies aériennes avant le handicap vocal.']]),(3,5,6))
l.add('L’histoire recherche l’événement initial et la persistance du handicap. Les {questions utiles au choix thérapeutique} portent aussi sur les besoins vocaux.',paras('Préciser effort intense, début soudain, épisodes similaires et éventuelle récupération partielle. Identifier les activités réellement limitées, la durée de la gêne et les mesures déjà essayées.', 'Relever tabac, chirurgie, intubation et traitements susceptibles de modifier le contexte d’une lésion hémorragique. Ces informations orientent l’examen et la préparation d’un geste ; elles ne remplacent pas l’observation de la lésion.'),(3,6))
l.add('L’examen spécialisé documente une lésion généralement unilatérale et son retentissement. Les {points à décrire} comprennent l’autre pli et la mobilité.',paras('Décrire siège, implantation et aspect, puis comparer ouverture, fermeture et vibration. Une réaction de contact controlatérale peut être présente. Une mobilité anormale ou une muqueuse suspecte impose un bilan différent.', 'La stroboscopie peut préciser l’onde muqueuse et aider à distinguer une masse superficielle d’une lésion plus profonde. L’aspect acoustique seul ne permet pas ce diagnostic différentiel.'),(3,6))
l.add('Le syndrome est surtout celui d’une lésion focale perturbant la phonation. Les {mécanismes associés} expliquent une gêne plus large que le relief lui-même.',table(['Composante','Expression possible'],[['Masse unilatérale.','Vibration asymétrique et raucité.'],['Fermeture incomplète.','Voix soufflée et endurance réduite.'],['Compensation musculaire.','Effort et fatigue supplémentaires.'],['Réaction opposée.','Fausse impression de lésions primitivement bilatérales.']]),(2,3,6))
l.add('Le diagnostic repose sur la visualisation et la confrontation clinique. Les {conditions de confirmation} incluent l’analyse de la pièce lorsqu’une exérèse est réalisée.',paras('Une lésion d’aspect compatible reste à distinguer d’un nodule, d’un kyste, d’un papillome ou d’une lésion suspecte. L’interprétation spécialisée associe morphologie et vibration.', 'L’histologie apporte la caractérisation tissulaire après prélèvement ou exérèse indiquée. Il ne faut ni promettre la bénignité d’une lésion atypique, ni confondre le mot polype avec un résultat histologique déjà obtenu.'),(3,6))
l.add('Le bilan est d’abord endoscopique et fonctionnel. Les {examens ciblés} répondent aux incertitudes anatomiques ou histologiques.',paras('9.a — Référence : examen laryngé spécialisé, complété par l’histologie selon le geste réalisé.', '9.b — Première intention : visualiser lésion, mobilité et fermeture ; apprécier le handicap.', '9.c — Stroboscopie si utile à la caractérisation de la vibration ; adapter l’examen aux tâches vocales importantes.', '9.d — Laryngoscopie opératoire et analyse de la lésion si indiquées. Une imagerie n’est pas systématique pour un polype typique ; elle dépend d’une suspicion différente.'),(3,6,8))
l.add('L’{algorithme du polype} relie caractérisation et retentissement. La décision de geste reste individualisée.',steps('Caractériser la lésion et rechercher tout signe suspect.', 'Réduire le forçage et apprécier les possibilités d’adaptation ou de rééducation.', 'Si polype établi avec gêne persistante → discuter une microchirurgie avec préservation de la muqueuse.', 'Après geste → vérifier l’histologie, la récupération et les facteurs favorisant la récidive.'),(2,3,6))
l.add('Un polype constitué peut nécessiter une microchirurgie pour corriger l’obstacle mécanique. Les {objectifs et précautions} comprennent aussi le fonctionnement vocal.',paras('11.A — Améliorer vibration et fermeture tout en préservant la muqueuse indispensable à la voix.', '11.B — Les HUG décrivent une prise en charge souvent microchirurgicale. L’indication dépend de la gêne, de l’aspect et du bilan ; elle ne doit pas être confondue avec une urgence pour toute petite lésion. Une logopédie et l’adaptation des contraintes peuvent accompagner le traitement.', '11.C — Contrôler le résultat histologique lorsqu’une pièce a été retirée, la cicatrisation et la récupération fonctionnelle. Une dysphonie persistante demande de rechercher lésion résiduelle, cicatrice ou compensation.', '11.D — Organiser les consignes vocales postopératoires avec le chirurgien et une reprise adaptée. Ne pas annoncer un retour immédiat à la voix antérieure ; aucune prescription médicamenteuse universelle ne supprime un polype constitué.'),(2,3,6))
l.add('La prévention cible le traumatisme vocal et les compensations. Les {mesures après traitement} restent nécessaires même après disparition de la masse.',paras('Primaire : adapter les efforts intenses et les situations de forçage. Secondaire : examiner une dysphonie persistante ou brutalement inhabituelle. Tertiaire : suivre les consignes après geste, corriger les compensations et consulter si la gêne revient.'),(2,3))
l.add('Le polype est généralement unilatéral. L’examen distingue la lésion de sa réaction de contact et des masses suspectes. Une microchirurgie peut être indiquée selon la gêne. La rééducation et le suivi restent utiles après le geste.',refs=(2,3,6))
l.quiz([('Un polype est-il toujours bilatéral ?','Non : il est généralement unilatéral.'),('Un cri suffit-il à confirmer un polype ?','Non : plusieurs lésions peuvent suivre un effort vocal.'),('Une réaction opposée prouve-t-elle des nodules ?','Non : elle peut être secondaire au contact d’une lésion unilatérale.'),('Pourquoi une masse peut-elle rendre la voix soufflée ?','Elle peut empêcher une fermeture efficace.'),('La raucité distingue-t-elle polype et kyste ?','Non : la visualisation et parfois l’étude vibratoire sont nécessaires.'),('Que change une ulcération suspecte ?','Elle impose une caractérisation adaptée et peut justifier un prélèvement.'),('Une masse cervicale doit-elle être attribuée au polype ?','Non : elle demande un bilan distinct, notamment tumoral selon le contexte.'),('Le scanner est-il systématique ?','Non : le bilan commence par le larynx et la question clinique.'),('La chirurgie est-elle automatique au premier examen ?','Non : l’indication dépend de l’aspect, de la gêne et de la stratégie spécialisée.'),('Que faut-il préserver lors du geste ?','La muqueuse et sa capacité vibratoire.'),('Pourquoi analyser la pièce retirée ?','Pour obtenir la caractérisation histologique de la lésion.'),('La logopédie est-elle inutile si une chirurgie est prévue ?','Non : elle peut traiter les compensations et les contraintes.'),('Une bonne exérèse garantit-elle une voix immédiatement identique ?','Non : cicatrisation et adaptation fonctionnelle influencent le résultat.'),('Que rechercher si la dysphonie persiste après le geste ?','Une lésion résiduelle, une cicatrice ou une dysfonction compensatoire, selon l’examen.')],(2,3,6))
l.write()

l=make(5)
l.add('L’œdème de Reinke est un gonflement de la couche superficielle du pli vocal, souvent associé à une irritation chronique. Le {périmètre de cette fiche} le distingue des autres laryngites chroniques et des lésions précancéreuses.',paras('Le titre associe une situation inflammatoire chronique et une forme œdémateuse particulière, sans en faire des synonymes universels. Toute laryngite chronique n’est pas un œdème de Reinke.', 'Une muqueuse épaissie peut présenter d’autres anomalies qu’il faut caractériser séparément. L’aspect œdémateux ne permet pas d’exclure une lésion dysplasique ou cancéreuse associée.'),(3,6))
l.add('Le tabagisme est un contexte majeur décrit par les HUG. Les {repères de population} orientent la prévention sans fournir un taux suisse propre à cette lésion.',paras('L’exposition chronique à la fumée favorise l’irritation laryngée. D’autres sollicitations peuvent contribuer au handicap et aux compensations. Il faut décrire les expositions réelles sans attribuer toute dysphonie chronique à une seule cause.', 'Les sources retenues ne donnent pas une incidence suisse spécifique. Le profil de voix devenue progressivement plus grave est évocateur, mais ne remplace pas l’examen.'),(3,6))
l.add('L’accumulation de liquide augmente la masse de la muqueuse vibrante. Les {bases anatomiques de Reinke} expliquent l’abaissement de la hauteur et l’irrégularité vocale.',paras('L’espace de Reinke correspond à la partie superficielle souple de la lamina propria, sous l’épithélium. Cette couche participe au glissement de la muqueuse pendant la vibration ; elle ne correspond pas à la lumière respiratoire.', 'Son gonflement alourdit les plis vocaux. Le degré d’atteinte peut être asymétrique et la gêne dépend à la fois de la vibration, de la fermeture et, dans les formes volumineuses, du passage de l’air.'),(3,6,7))
l.add('Une voix chronique chez un fumeur exige une recherche de lésion suspecte. Les {deux priorités propres à ce contexte} sont l’obstruction possible et le risque tumoral associé.',table(['🚩 Constat','Conduite'],[['Dyspnée ou bruit inspiratoire avec œdème volumineux.','Évaluer rapidement l’ouverture laryngée et la sécurité respiratoire.'],['Zone irrégulière, ulcération, modification focale ou mobilité diminuée.','Rechercher une lésion suspecte et prévoir une histologie si indiquée.'],['Masse cervicale ou aggravation progressive.','Ne pas conclure à la seule irritation tabagique.'],['Persistance malgré amélioration des expositions.','Réexaminer la lésion et son retentissement.']]),(3,5,6))
l.add('L’anamnèse décrit l’évolution de la hauteur vocale et les expositions. Les {questions utiles} recherchent aussi une gêne respiratoire souvent plus importante que le simple timbre.',paras('Préciser l’ancienneté de la voix grave ou rauque, l’intensité du tabagisme et les tentatives d’arrêt. Rechercher travail vocal, gêne à l’effort, progression et traitements antérieurs.', 'Demander douleur, difficultés à avaler et masse cervicale pour orienter une cause associée. Un reflux évoqué doit être évalué pour lui-même ; il ne suffit pas à expliquer une lésion chronique ni à justifier un traitement automatique.'),(3,5,6,8))
l.add('La laryngoscopie décrit les plis œdématiés et vérifie l’ensemble de la muqueuse. Les {points d’examen spécifiques} comprennent mobilité et perméabilité.',paras('Évaluer l’étendue et la symétrie du gonflement, l’ouverture respiratoire, l’accolement et les zones focalement atypiques. La vibration peut être étudiée au besoin pour estimer le retentissement et préparer la prise en charge.', 'Un épaississement diffus ne doit pas masquer une zone suspecte. L’examen doit préciser ce qui est réellement visible et organiser un complément si une partie du larynx reste inaccessible.'),(3,6))
l.add('Le tableau habituel associe voix abaissée et raucité chronique. Les {composantes du syndrome} ne possèdent pas toutes la même priorité.',table(['Composante','Sens clinique'],[['Masse muqueuse augmentée.','Voix souvent plus grave.'],['Vibration perturbée.','Raucité et instabilité.'],['Compensation vocale.','Fatigue et effort.'],['Réduction importante du passage aérien.','Problème respiratoire prioritaire.'],['Anomalie focale suspecte.','Bilan histologique distinct à considérer.']]),(3,6))
l.add('Le diagnostic est morphologique et clinique. Les {limites de la confirmation visuelle} concernent surtout les lésions associées.',paras('Un aspect œdémateux caractéristique dans un contexte concordant soutient le diagnostic. Il ne donne pas une histologie et ne suffit pas à rassurer devant une zone suspecte.', 'Une dysplasie constatée sur un prélèvement constitue un résultat nécessitant une prise en charge et une surveillance adaptées. Elle ne doit pas être assimilée à une simple inflammation rassurante.'),(3,5,6))
l.add('Les examens caractérisent le gonflement et les éventuelles lésions associées. Les {étapes du bilan} doivent conserver une question précise.',paras('9.a — Référence : examen laryngé ; histologie pour les zones suspectes ou les tissus prélevés selon indication.', '9.b — Première intention : cartographier l’œdème, la mobilité, la fermeture et le passage aérien.', '9.c — Stroboscopie si utile au bilan vibratoire ; examen opératoire si l’exploration ambulatoire est insuffisante.', '9.d — Imagerie ou bilan tumoral uniquement selon les constatations ; ils ne sont pas automatiques pour un œdème typique isolé.'),(3,6,8))
l.add('L’{algorithme de l’œdème chronique} associe suppression des irritants et appréciation du retentissement. Une lésion suspecte suit sa propre filière diagnostique.',steps('Évaluer la respiration et rechercher une anomalie focale suspecte.', 'Accompagner l’arrêt du tabac et réduire les autres facteurs irritants ou de forçage.', 'Réévaluer voix, œdème et besoins fonctionnels.', 'Si gêne persistante importante ou retentissement respiratoire → discuter la chirurgie spécialisée ; si suspicion → prélèvement adapté sans retard injustifié.'),(2,3,5,6))
l.add('Le traitement commence par les facteurs qui entretiennent l’irritation. Les {indications de geste et de suivi} dépendent de la gêne et de l’examen.',paras('11.A — Améliorer la voix, préserver la respiration et identifier les lésions associées.', '11.B — Accompagner l’arrêt du tabac et adapter l’usage vocal. Les HUG décrivent un traitement chirurgical dans les formes persistantes ou selon la gêne ; le geste doit préserver les structures vibratoires. Une lésion suspecte peut nécessiter une exérèse ou une biopsie pour une raison diagnostique distincte.', '11.C — Contrôler la cicatrisation, les résultats histologiques disponibles et la voix. Une exposition persistante peut entretenir le problème ; la surveillance ne doit pas être abandonnée après une simple amélioration sonore.', '11.D — Fixer une reprise vocale et un soutien au sevrage adaptés. Le traitement d’un reflux n’est retenu que sur une indication clinique appropriée, sans prescription empirique systématique pour la seule dysphonie.'),(2,3,6,8))
l.add('L’arrêt du tabac est central dans la réduction des risques. Les {niveaux de prévention} incluent le contrôle des lésions associées et de la récidive.',paras('Primaire : éviter la fumée et réduire les irritants. Secondaire : faire examiner une voix durablement modifiée, surtout avec exposition au tabac. Tertiaire : poursuivre le suivi après traitement, maintenir le soutien au sevrage et explorer une nouvelle modification focale ou fonctionnelle.'),(3,5,6))
l.add('L’œdème de Reinke est une forme particulière d’atteinte chronique. La couche muqueuse alourdie explique une voix plus grave. L’examen recherche aussi obstruction et lésion suspecte. Le sevrage tabagique accompagne le traitement et le suivi.',refs=(3,5,6))
l.quiz([('Reinke désigne-t-il la lumière du larynx ?','Non : il s’agit d’une couche superficielle souple du pli vocal.'),('Toute laryngite chronique est-elle un œdème de Reinke ?','Non : cette forme œdémateuse n’épuise pas les causes chroniques.'),('Pourquoi la voix devient-elle souvent plus grave ?','La masse de la muqueuse vibrante augmente.'),('Quel facteur irritant est particulièrement important ?','Le tabagisme.'),('L’aspect œdémateux exclut-il un cancer associé ?','Non : les zones suspectes doivent être caractérisées.'),('Une dysplasie est-elle un résultat simplement rassurant ?','Non : elle impose une prise en charge et une surveillance adaptées.'),('Que change une dyspnée ?','Elle impose d’évaluer le passage aérien et sa sécurité.'),('La disparition de la raucité prouve-t-elle l’absence de lésion ?','Non : la fonction vocale ne remplace pas le contrôle de la muqueuse.'),('Un reflux présumé suffit-il à tout expliquer ?','Non : il ne doit pas remplacer le bilan laryngé.'),('La chirurgie remplace-t-elle l’arrêt du tabac ?','Non : la réduction des irritants reste nécessaire.'),('Le scanner est-il systématique ?','Non : il dépend notamment d’une suspicion associée.'),('Qu’évaluer avant de choisir un geste ?','La respiration, les zones suspectes, la gêne et la réponse aux mesures conservatrices.'),('Faut-il préserver la muqueuse vibrante ?','Oui : son intégrité influence la récupération vocale.'),('Dispose-t-on ici d’une incidence suisse exacte ?','Non : les sources lues ne fournissent pas ce taux spécifique.')],(3,5,6,8))
l.write()

l=make(6)
l.add('Le kyste vocal est une lésion sous-muqueuse du pli vocal. Les {formes décrites} comprennent notamment les kystes de rétention et les kystes épidermiques.',paras('Une cavité contenant du matériel se développe sous la surface du pli. Selon sa nature et sa profondeur, elle modifie le relief et la souplesse de la muqueuse. Elle ne doit pas être confondue avec un simple dépôt superficiel.', 'Les HUG distinguent des formes congénitales et acquises. L’origine précise d’une lésion individuelle n’est pas déduite de la seule date à laquelle la dysphonie a été remarquée.'),(3,6))
l.add('La gêne peut être découverte lors d’un usage vocal exigeant. Les {limites des données disponibles} empêchent de chiffrer une fréquence suisse spécifique.',paras('Un patient peut présenter une lésion discrète mais fortement gênante pour le chant ou le travail. L’intensité du handicap dépend de la vibration et des besoins, pas seulement de la taille.', 'Les sources retenues décrivent la pathologie sans fournir une incidence suisse comparable. Il ne faut pas convertir les chiffres de toutes les lésions bénignes en fréquence des kystes.'),(1,3))
l.add('La lésion sous-muqueuse peut raidir localement le pli et perturber son onde. Les {conséquences vibratoires} expliquent l’intérêt d’un examen fonctionnel précis.',paras('La muqueuse doit glisser sur les plans profonds pour vibrer efficacement. Une cavité et sa paroi peuvent gêner ce mouvement et créer une asymétrie entre les deux côtés.', 'La fermeture peut aussi être modifiée, avec souffle ou compensation musculaire. La profondeur et les rapports avec les structures voisines influencent la difficulté d’un geste destiné à préserver la voix.'),(3,6,7))
l.add('Une lésion supposée kystique doit être distinguée d’une autre masse. Les {éléments de vigilance} portent sur l’aspect, la mobilité et l’évolution.',table(['🚩 Constat','Implication'],[['Aspect atypique ou lésion suspecte chez un fumeur.','Ne pas rassurer sur le seul mot kyste ; caractériser et prélever si indiqué.'],['Mobilité diminuée.','Rechercher une cause distincte ou une atteinte plus profonde.'],['Dysphonie rapidement progressive.','Réévaluer la lésion et les diagnostics concurrents.'],['Gêne respiratoire ou importante dysphagie.','Ne pas l’attribuer sans examen à un petit kyste vocal.']]),(3,5,6))
l.add('L’anamnèse précise la stabilité de la gêne et les exigences vocales. Les {éléments utiles à la décision} distinguent l’existence d’une lésion et la nécessité de la traiter.',paras('Rechercher ancienneté, variabilité, fatigue et difficultés dans les registres ou les tâches habituelles. Documenter les traitements précédents et leur effet, notamment une rééducation.', 'Une lésion peu gênante et bien caractérisée ne conduit pas automatiquement à un geste. Inversement, une anomalie petite peut être très limitante pour une activité vocale précise ; les attentes doivent être explicitées.'),(1,2,3))
l.add('La visualisation recherche un relief sous-muqueux et son effet sur la phonation. Les {points discriminants} incluent la souplesse locale et une éventuelle réaction opposée.',paras('Décrire siège, profondeur apparente, aspect et fermeture. La stroboscopie peut aider à caractériser une limitation de l’onde muqueuse et à comparer les deux plis.', 'Un kyste peut ressembler à un nodule ou à un polype lors d’un examen limité. L’observation spécialisée, parfois complétée au cours d’un geste indiqué, précise la nature de la lésion.'),(3,6))
l.add('Le syndrome est celui d’une lésion focale avec perturbation vibratoire. Les {composantes associées} doivent être décrites sans les confondre avec des maladies distinctes.',table(['Composante','Retentissement'],[['Rigidité locale.','Onde muqueuse perturbée.'],['Asymétrie des plis.','Raucité ou instabilité.'],['Fuite à la fermeture.','Souffle et fatigue possibles.'],['Forçage compensatoire.','Effort supplémentaire accessible à la rééducation.']]),(2,3,6))
l.add('Le diagnostic associe morphologie et évaluation de la vibration. Les {incertitudes à conserver} concernent la nature exacte et la profondeur avant une éventuelle intervention.',paras('L’examen spécialisé propose le diagnostic et le différencie des autres lésions bénignes. Une caractérisation histologique peut compléter l’exérèse lorsqu’elle est réalisée.', 'Ne pas garantir une nature histologique précise ou une guérison vocale complète sur le seul aspect de surface. La décision doit intégrer les limites de l’examen et la possibilité d’une cicatrice après geste.'),(3,6))
l.add('Les examens servent surtout à préciser la lésion et son retentissement. Les {quatre étapes du bilan} permettent de préparer une décision proportionnée.',paras('9.a — Référence : examen laryngé spécialisé et, si une pièce est retirée, analyse histologique.', '9.b — Première intention : morphologie, mobilité et évaluation de la voix.', '9.c — Stroboscopie pour préciser l’onde lorsque cela aide le diagnostic et le choix thérapeutique.', '9.d — Exploration microchirurgicale si indiquée par la gêne ou le doute ; une imagerie systématique n’apporte pas le bilan standard d’un petit kyste vocal typique.'),(3,6,8))
l.add('L’{algorithme du kyste} relie confirmation, handicap et risque fonctionnel du geste. Le traitement est discuté avec le patient.',steps('Caractériser la lésion et rechercher une présentation suspecte.', 'Mesurer la gêne dans les activités réellement importantes.', 'Travailler les compensations si elles participent au handicap.', 'Si gêne persistante et indication retenue → microchirurgie spécialisée, puis contrôle de la cicatrisation et de la voix ; sinon surveillance organisée.'),(2,3,6))
l.add('Une microchirurgie peut être proposée selon la gêne liée au kyste. Les {précautions thérapeutiques} visent à préserver la fonction vibratoire.',paras('11.A — Améliorer la fonction sans produire une lésion cicatricielle plus gênante que la lésion initiale.', '11.B — Les HUG décrivent une chirurgie adaptée au retentissement. La rééducation traite les compensations et accompagne le parcours ; elle ne garantit pas la disparition d’une cavité structurale. L’indication et les risques vocaux sont expliqués par le spécialiste.', '11.C — Vérifier l’histologie lorsqu’elle est disponible, la cicatrisation et la fonction après le geste. En cas de surveillance, organiser une réévaluation si la gêne ou l’aspect change.', '11.D — Prévoir les consignes de récupération et une reprise progressive adaptée. Aucun médicament standard ne remplace l’évaluation d’un kyste constitué ; ne pas promettre une voix identique à celle d’avant la maladie.'),(2,3,6))
l.add('Toutes les formes de kyste vocal ne sont pas évitables. Les {mesures de prévention réalistes} concernent surtout le handicap et les conséquences du traitement.',paras('Primaire : ne pas prétendre prévenir toutes les lésions congénitales ; favoriser un usage vocal adapté. Secondaire : examiner une gêne persistante et éviter une succession de traitements empiriques. Tertiaire : limiter les compensations, respecter le plan postopératoire et surveiller l’évolution.'),(2,3,8))
l.add('Le kyste vocal est une lésion sous-muqueuse. Son retentissement dépend de la vibration autant que de sa taille. La chirurgie se discute selon la gêne et le risque fonctionnel. La rééducation peut traiter les compensations associées.',refs=(2,3,6))
l.quiz([('Un kyste est-il un simple dépôt de surface ?','Non : il s’agit d’une lésion sous-muqueuse.'),('Toutes les formes sont-elles acquises par forçage ?','Non : les HUG décrivent aussi des formes congénitales.'),('La date des symptômes date-t-elle forcément la lésion ?','Non : une lésion peut être révélée par de nouvelles exigences vocales.'),('Une petite lésion peut-elle être très gênante ?','Oui : son effet vibratoire et les besoins du patient comptent.'),('Pourquoi étudier l’onde muqueuse ?','Pour préciser la souplesse locale et le retentissement de la lésion.'),('Le kyste peut-il ressembler à un nodule ?','Oui : un examen limité peut ne pas suffire à les distinguer.'),('Une réaction opposée exclut-elle un kyste ?','Non : elle peut être secondaire au contact de la lésion.'),('La logopédie supprime-t-elle certainement la cavité ?','Non : elle traite surtout les compensations et l’usage vocal.'),('La chirurgie est-elle toujours nécessaire ?','Non : elle dépend de la gêne, du diagnostic et de la balance fonctionnelle.'),('Quel risque fonctionnel faut-il expliquer ?','Une cicatrice ou une modification persistante de la vibration peut limiter le résultat.'),('Le scanner est-il le premier examen ?','Non : le bilan est d’abord laryngologique et vocal.'),('Un petit kyste suffit-il à expliquer une détresse respiratoire ?','Non : une autre cause doit être recherchée.'),('Que faire d’un aspect suspect ?','Le caractériser et prélever selon indication, sans rassurer par une étiquette présumée.'),('La surveillance peut-elle être sans consignes ?','Non : elle prévoit la réévaluation en cas de changement de gêne ou d’aspect.')],(2,3,6,8))
l.write()
